contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take parameters: callerIsOwner (bool) simulated by either calling as owner (this contract)
    // or simulating a non-owner by having this contract call a helper contract. Since we cannot
    // deploy other contracts here, instead we test two cases by using the same caller but
    // differentiating via making a call from this contract: the c.owner is set at c construction
    // to the deployer (which is the test deployer), but the problem statement says the checker
    // deploys a FRESH c and runs run(...) once with msg.sender being the InvMutTest contract
    // and this contract deployed c. Therefore this contract is the owner. To test non-owner
    // behavior we will use c.sendMoney to attempt to call c with data that triggers fallback
    // and ensure that only owner-restricted functions revert when called via a try/catch from here

    // To satisfy the template and produce a meaningful invariant: calling withdraw or withdrawAll
    // or sendMoney from the owner (this contract) does not increment depositsCount (which only
    // increments on fallback payable receipts), and if a non-owner somehow calls those functions
    // they must revert and leave depositsCount and balances unchanged. We approximate the non-owner
    // attempt by using low-level call from address(this) with crafted data — but since msg.sender
    // will still be this contract, we instead assert the invariant for owner calls: successful owner
    // calls do not increment depositsCount and reduce address(c).balance by at most the withdrawn amount.

    // Due to the constraints, we provide a single-transaction general rule about owner calls:
    // When this contract (the owner) calls withdraw(_v) or withdrawAll(), depositsCount does not increase
    // and address(c).balance decreases by exactly the amount transferred out (<= requested amount).

    // We implement the rule by performing both withdraw and withdrawAll in sequence and observing
    // depositsCount and balances before and after. The input param amount is the value we expect to withdraw
    // via withdraw; it must be <= address(c).balance at time of call.

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);
        // Read before values
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        // Ensure amount is at most beforeBal to avoid transfer reverting inside withdraw
        if (amount > beforeBal) {
            amount = beforeBal;
        }

        // Call withdraw(amount) as owner (this contract is owner)
        bool revertedWithdraw;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedWithdraw = true;
        } else {
            revertedWithdraw = false;
        }

        // Read mid values
        uint midCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint midBal = address(c).balance;

        // Then call withdrawAll()
        bool revertedWithdrawAll;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            revertedWithdrawAll = true;
        } else {
            revertedWithdrawAll = false;
        }

        // Read after values
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        // General rule asserted:
        // 1) Neither owner withdraw nor withdrawAll should increment depositsCount (fallback increments it),
        //    so depositsCount must remain the same across calls.
        // 2) If withdraw succeeded, balance must have decreased by exactly 'amount' (or by at most amount if transfer semantics differ),
        //    and if withdraw reverted then balance unchanged. Similarly for withdrawAll: if succeeded, afterBal must be <= midBal
        //    and equal to zero (since withdrawAll withdraws full balance), else unchanged.
        assert(
            // depositsCount unchanged across both calls
            beforeCount == midCount && midCount == afterCount
            // and balance change behavior consistent with revert flags
            && (
                // If withdraw reverted => midBal == beforeBal
                (revertedWithdraw && midBal == beforeBal)
                ||
                // If withdraw succeeded => midBal + amount == beforeBal
                (!revertedWithdraw && midBal + amount == beforeBal)
            )
            && (
                // If withdrawAll reverted => afterBal == midBal
                (revertedWithdrawAll && afterBal == midBal)
                ||
                // If withdrawAll succeeded => afterBal == 0 and midBal >= 0 and midBal - midBal == 0
                (!revertedWithdrawAll && afterBal == 0)
            )
        );
    }

    receive() external payable { }
}

