// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        uint256 beforeCount;
        try c.depositsCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        uint beforeBal = address(c).balance;
        if (amount > beforeBal) {
            amount = beforeBal;
        }
        bool revertedWithdraw;
        try c.withdraw(amount) {
            revertedWithdraw = false;
        } catch {
            revertedWithdraw = true;
        }
        uint256 midCount;
        try c.depositsCount() returns (uint256 __r) { midCount = __r; } catch { return; }
        uint midBal = address(c).balance;
        bool revertedWithdrawAll;
        try c.withdrawAll() {
            revertedWithdrawAll = false;
        } catch {
            revertedWithdrawAll = true;
        }
        uint256 afterCount;
        try c.depositsCount() returns (uint256 __r) { afterCount = __r; } catch { return; }
        uint afterBal = address(c).balance;
        assertTrue(beforeCount == midCount && midCount == afterCount
            // and balance change behavior consistent with revert flags
            && (
                // If withdraw reverted => midBal == beforeBal
                (revertedWithdraw && midBal == beforeBal)
                ||
                // If withdraw succeeded => midBal + amount == beforeBal
                (!revertedWithdraw && midBal + amount == beforeBal)
            )
            && (
                // If withdrawAll reverted => afterBal == midBal
                (revertedWithdrawAll && afterBal == midBal)
                ||
                // If withdrawAll succeeded => afterBal == 0 and midBal >= 0 and midBal - midBal == 0
                (!revertedWithdrawAll && afterBal == 0)
            ));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable { }
}
